    fun get(language: String, key: String): String {
        val index = keys.indexOf(key)
        if (index < 0) return key
        return (catalog[language] ?: catalog.getValue("es"))[index]
    }
    fun categoryLabel(language: String, key: String): String {
        val index = categoryKeys.indexOf(key)
        if (index < 0) return key.replace('-', ' ')
        return (categoryNames[language] ?: categoryNames.getValue("es"))[index]
    }
